def _should_enter(self, drone, wall_left):
        if wall_left > self.ENTER_WALL:
            return False
        if int(drone.previous_inventory or 0) <= 0:
            return False
        self._bomb1 = self._first_bomb(drone)
        if self._bomb1 is None:
            return False
        return self._stalled()
